SELECT title
FROM courses
WHERE course_id IN (SELECT course_id FROM enrollments WHERE learner_id = 1);

SELECT display_name
FROM learners AS l
WHERE EXISTS (SELECT 1 FROM enrollments AS e WHERE e.learner_id = l.learner_id);

SELECT title
FROM courses
WHERE course_id IN (SELECT course_id FROM lesson_results GROUP BY course_id HAVING AVG(score) > 80);

SELECT learner_id, score
FROM lesson_results
WHERE score > (SELECT AVG(score) FROM lesson_results);
